arguments.new_string:
def parse(text, strict=False):
    """Split a comma-separated line into fields."""
    parts = [part.strip() for part in text.split(",")]
    if strict:
        for part in parts:
            if not part:
                raise ValueError("Empty field found in strict mode")
    return parts
